const soon = new Date(Date.now() + 3600 * 1000);
beforeEach(() => {
  cy.task('seedEvent', { title: 'Pizza night', startsAt: soon.toISOString().slice(0, 16) });
});
it("shows tonight's event first", () => {
  cy.visit('/events');
  cy.get('.event-card').first().should('contain', 'Tonight');
});
